def esc(t):
    s = str(t)
    s = s.replace("&", "&amp;")
    s = s.replace("<", "&lt;")
    s = s.replace(">", "&gt;")
    return s


def now_ts():
    return int(time.time())


def prm():
    try:
        p = params
    except:
        return ""
    if p is None:
        return ""
    s = str(p).strip()
    if s == "None":
        return ""
    return s


def tg_name():
    try:
        fu = message.get("from")
        if fu:
            n = fu.get("first_name")
            if n:
                return str(n)
            un = fu.get("username")
            if un:
                return "@" + str(un)
    except:
        pass
    return "Игрок"


def is_cancel(t):
    s = str(t).strip().lower()
    return s in ["/cancel", "cancel", "отмена", "/отмена"]


def pos_label(code):
    if not code:
        return "не выбрана"
    return POS_NAMES.get(str(code), str(code))


def fmt_left(sec):
    sec = int(sec)
    if sec < 0:
        sec = 0
    d = sec // 86400
    h = (sec % 86400) // 3600
    m = (sec % 3600) // 60
    if d > 0:
        return str(d) + " д " + str(h) + " ч"
    if h > 0:
        return str(h) + " ч " + str(m) + " мин"
    return str(m) + " мин"


