def find_user(q):
    s = str(q or "").strip()
    if not s:
        return ""
    if s.startswith("@"):
        s = s[1:]
    if s.isdigit():
        return s
    key = s.lower()
    v = tg_index_get(key)
    if v:
        return v
    try:
        ui = Bot.getData("users_index") or {}
    except:
        ui = {}
    if not isinstance(ui, dict):
        return ""
    for k in ui.keys():
        if str(ui.get(k) or "").strip().lower() == key:
            return str(k)
    for k in ui.keys():
        if str(pget(str(k), "tg_username", "") or "").strip().lower() == key:
            return str(k)
    for k in ui.keys():
        if key in str(ui.get(k) or "").strip().lower():
            return str(k)
    return ""


def club_lookup(q):
    key = str(q or "").strip().lower()
    if not key:
        return ""
    seed_official_clubs()
    if get_club(key):
        return key
    ids = get_club_ids()
    for cid in ids:
        c = get_club(cid)
        if not c:
            continue
        if str(c.get("name")).strip().lower() == key:
            return str(cid)
    for cid in ids:
        c = get_club(cid)
        if not c:
            continue
        nm = str(c.get("name")).strip().lower()
        if key in nm or nm in key:
            return str(cid)
    for pair in official_clubs():
        key2 = str(pair[0])
        nm2 = str(pair[1]).lower()
        if key in nm2 or nm2 in key:
            if get_club(key2):
                return key2
    return ""


